<?php
declare(strict_types=1);
require __DIR__ . '/config.php';

// Secure session defaults for local and HTTPS installations.
ini_set('session.use_strict_mode', '1');
session_name(SESSION_NAME);
session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off','samesite'=>'Lax','path'=>'/']);
session_start();
try { $pdo = new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4', DB_USER, DB_PASS, [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES=>false]); }
catch (PDOException $e) { http_response_code(500); exit('Database unavailable. Import schema.sql and check config.php.'); }

// Older local installs may have been imported before login throttling was added.
// This additive table creation is safe to repeat and prevents login from crashing
// while the owner upgrades an existing XAMPP database.
try {
    $pdo->exec("CREATE TABLE IF NOT EXISTS login_attempts (
        id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        email VARCHAR(190) NOT NULL,
        attempted_at DATETIME NOT NULL,
        INDEX idx_login_email_time (email, attempted_at)
    ) ENGINE=InnoDB");
} catch (PDOException $e) {
    error_log('FreshStock could not prepare login rate limiting: ' . $e->getMessage());
    http_response_code(500);
    exit('The login security table is missing. Import database_migrations/001_login_attempts.sql in phpMyAdmin.');
}

function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function check_csrf(): void { if (!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(419); exit('Session expired. Please go back and retry.'); } }
function user_id(): int { return (int)($_SESSION['user_id'] ?? 0); }
function require_login(): void { if (!user_id()) { header('Location: ?page=login'); exit; } }
function flash(string $msg): void { $_SESSION['flash'] = $msg; }
function redirect(string $page='dashboard'): never { header('Location: ?page='.rawurlencode($page)); exit; }
function field(string $key, int $max=180): string { return mb_substr(trim((string)($_POST[$key] ?? '')),0,$max); }
function owned_supplier(PDO $pdo, int $id): bool { $s=$pdo->prepare('SELECT id FROM suppliers WHERE id=? AND user_id=?'); $s->execute([$id,user_id()]); return (bool)$s->fetchColumn(); }
function pro(): bool { return ($_SESSION['plan'] ?? 'free') === 'pro'; }
require_once __DIR__ . '/app/Operations.php';

$page = isset($_GET['track']) ? 'tracking' : (string)($_GET['page'] ?? (user_id() ? (($_SESSION['role']??'admin')==='rider'?'rider_dashboard':'dashboard') : 'home'));
if ($_SERVER['REQUEST_METHOD']==='POST') {
 check_csrf(); $action=(string)($_POST['action']??'');
 operations_handle_post($pdo,$action);
 if ($action==='signup') {
  $name=field('name',120); $email=strtolower(field('email',190)); $pw=(string)($_POST['password']??'');
  if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($pw)<8) { flash('Enter a name, valid email, and password of at least 8 characters.'); redirect('signup'); }
  try { $s=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)'); $s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]); flash('Account created. Sign in to continue.'); redirect('login'); }
  catch (PDOException $e) {
   // Only a uniqueness conflict means the email is registered. Other database
   // failures must not be disguised as a duplicate-account message.
   if ($e->getCode()==='23000') flash('That email address is already registered. Sign in with it instead.');
   else { error_log('FreshStock signup database error: '.$e->getMessage()); flash('We could not create the account because the database is not up to date. Contact the site administrator.'); }
   redirect('signup');
  }
 }
 if ($action==='login') {
  $email=strtolower(field('email',190)); $now=date('Y-m-d H:i:s');
  $s=$pdo->prepare('SELECT COUNT(*) FROM login_attempts WHERE email=? AND attempted_at > DATE_SUB(NOW(), INTERVAL 15 MINUTE)'); $s->execute([$email]);
  if ((int)$s->fetchColumn()>=5) { flash('Too many attempts. Wait 15 minutes before trying again.'); redirect('login'); }
  $s=$pdo->prepare('SELECT id,name,email,password_hash,plan,two_factor_enabled,role,owner_id FROM users WHERE email=?'); $s->execute([$email]); $u=$s->fetch();
  if (!$u || !password_verify((string)($_POST['password']??''),$u['password_hash'])) { $pdo->prepare('INSERT INTO login_attempts(email,attempted_at) VALUES(?,?)')->execute([$email,$now]); flash('Email or password was not recognized.'); redirect('login'); }
  $pdo->prepare('DELETE FROM login_attempts WHERE email=?')->execute([$email]);
  if ($u['two_factor_enabled']) { $code=(string)random_int(100000,999999); $pdo->prepare('DELETE FROM verification_codes WHERE user_id=?')->execute([$u['id']]); $pdo->prepare('INSERT INTO verification_codes(user_id,code_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(), INTERVAL 10 MINUTE))')->execute([$u['id'],password_hash($code,PASSWORD_DEFAULT)]); $_SESSION['pending_user']=(int)$u['id']; mail($u['email'],'FreshStock verification code',"Your code is $code. It expires in 10 minutes.",'From: '.OTP_FROM_EMAIL); flash('A verification code was sent to your email.'); redirect('verify'); }
  session_regenerate_id(true); $_SESSION['user_id']=(int)$u['id']; $_SESSION['name']=$u['name']; $_SESSION['plan']=$u['plan']; $_SESSION['role']=$u['role']??'admin'; $_SESSION['owner_id']=$u['owner_id']??null; redirect(($_SESSION['role']==='rider')?'rider_dashboard':'dashboard');
 }
 if ($action==='verify') {
  $uid=(int)($_SESSION['pending_user']??0); $s=$pdo->prepare('SELECT id,code_hash FROM verification_codes WHERE user_id=? AND expires_at>NOW() ORDER BY id DESC LIMIT 1'); $s->execute([$uid]); $v=$s->fetch();
  if (!$v || !password_verify(field('code',6),$v['code_hash'])) { flash('Invalid or expired verification code.'); redirect('verify'); }
  $s=$pdo->prepare('SELECT id,name,plan,role,owner_id FROM users WHERE id=?'); $s->execute([$uid]); $u=$s->fetch(); if (!$u) redirect('login');
  session_regenerate_id(true); unset($_SESSION['pending_user']); $_SESSION['user_id']=(int)$u['id']; $_SESSION['name']=$u['name']; $_SESSION['plan']=$u['plan']; $_SESSION['role']=$u['role']??'admin'; $_SESSION['owner_id']=$u['owner_id']??null; $pdo->prepare('DELETE FROM verification_codes WHERE user_id=?')->execute([$uid]); redirect(($_SESSION['role']==='rider')?'rider_dashboard':'dashboard');
 }
 if ($action==='logout') { $_SESSION=[]; session_regenerate_id(true); redirect('home'); }
 require_login(); $uid=user_id();
 if ($action==='product_save') {
  if (!pro() && empty($_POST['id'])) { $count=$pdo->prepare('SELECT COUNT(*) FROM products WHERE user_id=?'); $count->execute([$uid]); if((int)$count->fetchColumn()>=50){flash('The Free plan supports up to 50 products. Upgrade to Pro for unlimited products.');redirect('upgrade');} }
  if (!pro() && empty($_POST['id'])) { $count=$pdo->prepare('SELECT COUNT(*) FROM products WHERE user_id=?'); $count->execute([$uid]); if((int)$count->fetchColumn()>=50){flash('The Free plan supports up to 50 products. Upgrade to Pro for unlimited products.');redirect('upgrade');} }
  $id=(int)($_POST['id']??0); $name=field('name'); $code=field('code',100); $qty=max(0,(float)($_POST['quantity']??0)); $threshold=max(0,(float)($_POST['low_stock_threshold']??0)); $cost=max(0,(float)($_POST['unit_cost']??0)); $sid=(int)($_POST['supplier_id']??0); if($sid && !owned_supplier($pdo,$sid)) $sid=0;
  $expiry=(string)($_POST['expiry_date']??''); if($expiry!=='' && !preg_match('/^\d{4}-\d{2}-\d{2}$/',$expiry)) $expiry='';
  $data=[$sid?:null,$name,$code?:null,$qty,$threshold,field('unit',30)?:'units',$cost,field('storage_location',120)?:null,$expiry?:null,isset($_POST['is_perishable'])?1:0];
  if ($name==='') { flash('Product name is required.'); redirect('inventory'); }
  if ($id) { $data[]=$id; $data[]=$uid; $pdo->prepare('UPDATE products SET supplier_id=?,name=?,code=?,quantity=?,low_stock_threshold=?,unit=?,unit_cost=?,storage_location=?,expiry_date=?,is_perishable=? WHERE id=? AND user_id=?')->execute($data); }
  else { array_unshift($data,$uid); $pdo->prepare('INSERT INTO products(user_id,supplier_id,name,code,quantity,low_stock_threshold,unit,unit_cost,storage_location,expiry_date,is_perishable) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute($data); }
  flash('Product saved.'); redirect('inventory');
 }
 if ($action==='product_delete') { $pdo->prepare('DELETE FROM products WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$uid]); flash('Product deleted.'); redirect('inventory'); }
 if ($action==='supplier_save') { $name=field('name',160); if($name===''){flash('Supplier name is required.');redirect('suppliers');} $pdo->prepare('INSERT INTO suppliers(user_id,name,phone,email,notes) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE phone=VALUES(phone),email=VALUES(email),notes=VALUES(notes)')->execute([$uid,$name,field('phone',40)?:null,field('email',190)?:null,field('notes',500)?:null]); flash('Supplier saved.'); redirect('suppliers'); }
 if ($action==='supplier_delete') { $pdo->prepare('DELETE FROM suppliers WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$uid]); flash('Supplier deleted.'); redirect('suppliers'); }
 if ($action==='enable_2fa') { $pdo->prepare('UPDATE users SET two_factor_enabled=1 WHERE id=?')->execute([$uid]); flash('Email verification enabled. Configure PHP mail() in XAMPP to receive codes.'); redirect('security'); }
 if ($action==='upgrade') { $pdo->prepare("INSERT INTO subscriptions(user_id,amount,status) VALUES(?,500,'pending')")->execute([$uid]); flash('Demo M-Pesa request recorded as pending. Add Daraja credentials and callback details to complete payment.'); redirect('upgrade'); }
}

// JSON endpoints power customer tracking polling and administrator map refresh.
if (($_GET['api']??'')==='track') op_json_snapshot($pdo,(string)($_GET['token']??''));
if (($_GET['api']??'')==='delivery_snapshot') op_json_admin_snapshot($pdo,(int)($_GET['id']??0));
if (isset($_GET['export']) && in_array((string)$_GET['export'],['orders_csv','customers_csv','deliveries_csv'],true)) op_handle_export($pdo,(string)$_GET['export']);

// CSV and Excel-compatible exports. All records are scoped to the current user.
if (isset($_GET['export'])) { require_login(); $fmt=(string)$_GET['export']; $s=$pdo->prepare('SELECT p.name,p.code,p.quantity,p.unit,p.low_stock_threshold,p.unit_cost,p.storage_location,p.expiry_date,p.is_perishable,s.name supplier FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id AND s.user_id=p.user_id WHERE p.user_id=? ORDER BY p.name'); $s->execute([user_id()]); $rows=$s->fetchAll();
 if($fmt==='pdf'){ $lines=['FreshStock Inventory']; foreach($rows as $r)$lines[]=implode(' | ',array_map(fn($x)=>(string)$x,[$r['name'],$r['code'],$r['quantity'].' '.$r['unit'],'$'.$r['unit_cost'],$r['expiry_date']])); $text=implode("\n",array_slice($lines,0,48)); $stream="BT /F1 10 Tf 50 790 Td ".implode(' ',array_map(fn($line)=>'('.str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$line).') Tj 0 -15 Td',explode("\n",$text)))." ET"; $pdf="%PDF-1.4\n"; $objs=['1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj','2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj','3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >> endobj','4 0 obj << /Type /Font /Subtype /Type1 /BaseFont /Helvetica >> endobj','5 0 obj << /Length '.strlen($stream)." >> stream\n$stream\nendstream endobj"]; $offsets=[0]; foreach($objs as $o){$offsets[]=strlen($pdf);$pdf.="$o\n";} $xref=strlen($pdf); $pdf.="xref\n0 6\n0000000000 65535 f \n"; for($i=1;$i<=5;$i++)$pdf.=sprintf('%010d 00000 n ', $offsets[$i])."\n"; $pdf.="trailer << /Size 6 /Root 1 0 R >>\nstartxref\n$xref\n%%EOF"; header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename=inventory.pdf');echo $pdf;exit; }
 header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename=inventory.'.$fmt); $out=fopen('php://output','w'); fwrite($out,"\xEF\xBB\xBF"); fputcsv($out,['Product','Barcode','Quantity','Unit','Low stock threshold','Unit cost','Storage','Expiry','Perishable','Supplier']); foreach($rows as $r)fputcsv($out,$r); fclose($out); exit; }

$logged=(bool)user_id() && !isset($_GET['track']); if($logged) require_login(); $adminUI=$logged && (($_SESSION['role']??'admin')==='admin');
$flash=$_SESSION['flash']??''; unset($_SESSION['flash']);
$titles=['home'=>'Welcome','dashboard'=>'Dashboard','inventory'=>'Inventory Management','suppliers'=>'Suppliers','alerts'=>'Stock alerts','reports'=>'Reports & Analytics','orders'=>'Orders','order_view'=>'Order details','customers'=>'Customers','customer_view'=>'Customer profile','deliveries'=>'Deliveries','delivery_view'=>'Delivery details','rider_dashboard'=>'Rider workspace','tracking'=>'Order tracking','account'=>'My Account','help'=>'Help & Support','upgrade'=>'Upgrade to Pro','security'=>'Settings & Security','signup'=>'Create account','login'=>'Sign in','verify'=>'Verification']; $title=$titles[$page]??'FreshStock';
