<div class="page-heading"><div><div class="eyebrow"><i></i> YOUR STORE AT A GLANCE</div><h1>Good day, <?=h(explode(' ',trim($_SESSION['name']??'there'))[0])?> <span class="wave">✳</span></h1><p>Here’s what’s happening with your inventory today.</p></div><a class="button primary" href="?page=inventory#product-form">＋ Add product</a></div><section class="stats-grid"><article class="stat-card"><div class="stat-head"><span>Total products</span><i class="stat-icon green">▤</i></div><strong><?=number_format((int)$summary['total'])?></strong><small>In your inventory</small></article><article class="stat-card"><div class="stat-head"><span>Low stock</span><i class="stat-icon amber">↘</i></div><strong><?=number_format((int)$summary['low_count'])?></strong><small>At or below threshold</small></article><article class="stat-card"><div class="stat-head"><span>Expiring soon</span><i class="stat-icon coral">◷</i></div><strong><?=number_format((int)$summary['expiry_count'])?></strong><small>Within the next 7 days</small></article><article class="stat-card"><div class="stat-head"><span>Stock value</span><i class="stat-icon blue">◈</i></div><strong>$<?=number_format((float)$summary['stock_value'],2)?></strong><small>Based on unit cost</small></article></section><?php $stockChart=rows($pdo,'SELECT name,quantity,low_stock_threshold FROM products WHERE user_id=? ORDER BY quantity DESC LIMIT 10',[$u]); $chartMax=1; foreach($stockChart as $cp)$chartMax=max($chartMax,(float)$cp['quantity'],(float)$cp['low_stock_threshold']); ?><section class="chart-grid"><div class="chart-panel"><div class="chart-title"><div><h2>Stock level status</h2><p>Current quantity compared with each product threshold</p></div><span><i class="legend-current"></i> Stock <i class="legend-threshold"></i> Threshold</span></div><?php if(!$stockChart): ?><div class="chart-empty">Add products to see your stock levels here.</div><?php else: ?><div class="stock-bars"><?php foreach($stockChart as $cp): ?><div class="stock-bar-i